import Docxtemplater from "docxtemplater";
import PizZip from "pizzip";
import { readFileSync } from "fs";
import { promisify } from "util";
import libre from "libreoffice-convert";

const convert = promisify(libre.convert.bind(libre)) as
    (docx: Buffer, ext: string, filter?: string) => Promise<Buffer>;

/**
 * Vult een .docx-template met `data` en geeft het resultaat terug als .docx-buffer.
 *
 * Placeholders in de template zijn `{naam}` (zie docxtemplater-syntax). Ontbrekende
 * placeholders worden leeggelaten in plaats van als "undefined" gerenderd.
 *
 * @param template Pad naar het .docx-bestand, of de inhoud ervan als Buffer.
 * @param data Object met een key per placeholder in de template.
 * @returns De gevulde .docx als Buffer — schrijf weg met `fs.writeFileSync`, of geef
 *          door aan {@link naarPDF}.
 * @throws Bij een templatefout, met de uitleg per ontbrekende/kapotte placeholder.
 *
 * @example
 * const docx = vulTemplate("./templates/brief.docx", { naam: "Jansen BV", premie: "1.234,00" });
 * const pdf = await naarPDF(docx);
 */
export function vulTemplate(template: string | Buffer, data: Record<string, unknown>): Buffer {
    const content = typeof template === "string" ? readFileSync(template) : template;

    const doc = new Docxtemplater(new PizZip(content), {
        paragraphLoop: true,
        linebreaks: true,
        nullGetter: () => "",
    });

    try {
        doc.render(data);
    } catch (e: any) {
        // Docxtemplater gooit "Multi error"; de bruikbare info zit in properties.errors
        const uitleg = e.properties?.errors
            ?.map((err: any) => err.properties?.explanation)
            .filter(Boolean)
            .join("\n");
        throw new Error(`Template renderen mislukt:\n${uitleg || e.message}`);
    }

    return doc.toBuffer();
    // Oudere docxtemplater: doc.getZip().generate({ type: "nodebuffer", compression: "DEFLATE" })
}

/**
 * Converteert een .docx-buffer naar PDF via de lokaal geïnstalleerde LibreOffice.
 *
 * Let op: LibreOffice draait onder water als één proces met een gedeeld profiel.
 * Parallelle aanroepen (bijv. in een `Promise.all`) falen daardoor onregelmatig —
 * converteer op volgorde, in een gewone `for`-loop.
 *
 * @param docx De .docx als Buffer, bijvoorbeeld uit {@link vulTemplate}.
 * @returns De PDF als Buffer.
 * @throws Als LibreOffice niet geïnstalleerd is of de conversie mislukt.
 */
export function naarPDF(docx: Buffer): Promise<Buffer> {
    return convert(docx, ".pdf", undefined);
}